{"command":"cat <<'EOF' > compile.sh
#!/bin/bash
go mod tidy
go build -o executable main.go
EOF

cat <<'EOF' > main.go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
    "text/tabwriter"

	"github.com/olekukonko/tablewriter"
	"github.com/spf13/cobra"
)

type HostEntry struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP"`
	Host    string `json:"Host"`
}

var hostFile string
var outFormat string
var columns []string

func main() {
	rootCmd := &cobra.Command{
		Use:   "hostctl",
		Short: "hostctl is a CLI tool to manage your hosts file with ease.",
	}

	rootCmd.PersistentFlags().StringVar(&hostFile, "host-file", "/etc/hosts", "Hosts file path")
	rootCmd.PersistentFlags().StringVarP(&outFormat, "out", "o", "table", "Output type (table|raw|markdown|json)")
	rootCmd.PersistentFlags().StringSliceVarP(&columns, "column", "c", []string{}, "Column names to show on lists. comma separated")

	listCmd := &cobra.Command{
		Use:   "list",
		Short: "Shows a detailed list of profiles on your hosts file.",
		Run: func(cmd *cobra.Command, args []string) {
			runList()
		},
	}

	rootCmd.AddCommand(listCmd)

	if err := rootCmd.Execute(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func runList() {
	fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFile)
	entries, err := parseHostsFile(hostFile)
	if err != nil {
		fmt.Printf("[✖] error: %v\n", err)
		return
	}

	displayEntries(entries)
}

func parseHostsFile(path string) ([]HostEntry, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	var entries []HostEntry
	scanner := bufio.NewScanner(file)

	inManagedSection := false
	currentProfile := ""
	profileStatus := "on"

	headerFound := 0

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		if trimmed == "##################################################################" {
			headerFound++
			if headerFound == 3 {
				inManagedSection = true
				continue
			}
			continue
		}
		if strings.Contains(line, "Content under this line is handled by hostctl") {
			continue
		}

		if inManagedSection {
			if strings.HasPrefix(trimmed, "# profile.on") {
				currentProfile = strings.TrimSpace(strings.TrimPrefix(trimmed, "# profile.on"))
				profileStatus = "on"
				continue
			}
			if strings.HasPrefix(trimmed, "# profile.off") {
				currentProfile = strings.TrimSpace(strings.TrimPrefix(trimmed, "# profile.off"))
				profileStatus = "off"
				continue
			}
			if trimmed == "# end" {
				currentProfile = ""
				continue
			}
			if currentProfile != "" {
				l := trimmed
				if profileStatus == "off" && strings.HasPrefix(l, "#") {
					l = strings.TrimSpace(strings.TrimPrefix(l, "#"))
				}
				if l == "" || strings.HasPrefix(l, "#") {
					continue
				}
				parts := strings.Fields(l)
				if len(parts) >= 2 {
					ip := parts[0]
					for _, host := range parts[1:] {
						entries = append(entries, HostEntry{
							Profile: currentProfile,
							Status:  profileStatus,
							IP:      ip,
							Host:    host,
						})
					}
				}
			}
		} else {
			if trimmed == "" || strings.HasPrefix(trimmed, "#") {
				continue
			}
			parts := strings.Fields(trimmed)
			if len(parts) >= 2 {
				ip := parts[0]
				for _, host := range parts[1:] {
					entries = append(entries, HostEntry{
						Profile: "default",
						Status:  "on",
						IP:      ip,
						Host:    host,
					})
				}
			}
		}
	}
	return entries, scanner.Err()
}

func displayEntries(entries []HostEntry) {
	if outFormat == "json" {
		data, _ := json.Marshal(entries)
		fmt.Println(string(data))
		return
	}

    var filteredCols []string
    if len(columns) > 0 {
        for _, c := range columns {
            filteredCols = append(filteredCols, strings.ToUpper(c))
        }
    } else {
        filteredCols = []string{"PROFILE", "STATUS", "IP", "DOMAIN"}
    }

	if outFormat == "table" || outFormat == "markdown" {
		table := tablewriter.NewWriter(os.Stdout)
		table.SetHeader(filteredCols)

		if outFormat == "markdown" {
			table.SetBorders(tablewriter.Border{Left: true, Top: false, Right: true, Bottom: false})
			table.SetCenterSeparator("|")
		} else {
			table.SetAlignment(tablewriter.ALIGN_LEFT)
		}

		for _, e := range entries {
            row := []string{}
            for _, col := range filteredCols {
                switch col {
                case "PROFILE": row = append(row, e.Profile)
                case "STATUS": row = append(row, e.Status)
                case "IP": row = append(row, e.IP)
                case "DOMAIN": row = append(row, e.Host)
                }
            }
			table.Append(row)
		}
		table.Render()
	} else if outFormat == "raw" {
		w := tabwriter.NewWriter(os.Stdout, 0, 8, 1, '\t', 0)
        fmt.Fprintf(w, "%s\n", strings.Join(filteredCols, "\t"))
		for _, e := range entries {
            row := []string{}
            for _, col := range filteredCols {
                switch col {
                case "PROFILE": row = append(row, e.Profile)
                case "STATUS": row = append(row, e.Status)
                case "IP": row = append(row, e.IP)
                case "DOMAIN": row = append(row, e.Host)
                }
            }
			fmt.Fprintf(w, "%s\n", strings.Join(row, "\t"))
		}
		w.Flush()
	}
}
EOF
