        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        runList()
    }
}

func runBackup() {
    if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath) }
    timestamp := time.Now().Format("20060102")
    backupPath := hostFilePath + "." + timestamp
    input, err := os.ReadFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    err = os.WriteFile(backupPath, input, 0644)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[✔] Backup '%s' created.\n\n", backupPath)
        runList()
    }
}

func runRestore(args []string) {
    var fromFile string
    for i, arg := range args {
        if arg == "--from" && i+1 < len(args) { fromFile = args[i+1]; break }
    }
    if fromFile == "" { return }
    input, err := os.ReadFile(fromFile)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    err = os.WriteFile(hostFilePath, input, 0644)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        fmt.Printf("[✔] File '%s' restored.\n\n", fromFile)
        runList()
    }
}

func runReplace(args []string) {
    if len(args) == 0 { return }
    profileName := args[0]
    var fromFile string
    for i, arg := range args {
        if (arg == "-f" || arg == "--from") && i+1 < len(args) { fromFile = args[i+1]; break }
    }
    if fromFile == "" { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    entries, err := readEntriesFromFile(fromFile)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    found := false
    for i, p := range hf.Profiles {
        if p.Name == profileName { hf.Profiles[i].Entries = entries; found = true; break }
    }
    if !found { hf.Profiles = append(hf.Profiles, Profile{Name: profileName, On: true, Entries: entries}) }
    err = hf.Save()
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        runList()
    }
}
