cat <<'EOF' > main.go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"
)

const (
	HeaderStart  = "##################################################################"
	HeaderMiddle = "# Content under this line is handled by hostctl. DO NOT EDIT."
	HeaderEnd    = "##################################################################"
)

type HostEntry struct {
	IP      string
	Domains []string
}

type Profile struct {
	Name   string
	On     bool
	Entries []HostEntry
}

type HostFile struct {
	Path      string
	PreHeader []string
	Profiles  []Profile
}

type row struct {
    profile string
    status  string
    ip      string
    domain  string
}

var (
	hostFilePath = "/etc/hosts"
	outFormat    = "table"
	columns      = []string{"PROFILE", "STATUS", "IP", "DOMAIN"}
	quiet        = false
)

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		printHelp()
		return
	}

	newArgs := []string{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--host-file" && i+1 < len(args) {
			hostFilePath = args[i+1]
			i++
		} else if strings.HasPrefix(arg, "--host-file=") {
			hostFilePath = strings.TrimPrefix(arg, "--host-file=")
		} else if (arg == "-o" || arg == "--out") && i+1 < len(args) {
			outFormat = args[i+1]
			i++
		} else if strings.HasPrefix(arg, "--out=") {
			outFormat = strings.TrimPrefix(arg, "--out=")
		} else if (arg == "-c" || arg == "--column") && i+1 < len(args) {
			columns = strings.Split(strings.ToUpper(args[i+1]), ",")
			i++
		} else if arg == "--raw" {
			outFormat = "raw"
		} else if arg == "-q" || arg == "--quiet" {
			quiet = true
		} else if arg == "-v" || arg == "--version" {
			fmt.Println("hostctl version dev")
			return
		} else {
			newArgs = append(newArgs, arg)
		}
	}

	if len(newArgs) == 0 {
		printHelp()
		return
	}

	cmd := newArgs[0]
	cmdArgs := newArgs[1:]

	switch cmd {
	case "list":
		runList()
	case "status":
		runStatus()
	case "add":
		runAdd(cmdArgs)
	case "remove":
		runRemove(cmdArgs)
	case "enable":
		runEnable(cmdArgs)
	case "disable":
		runDisable(cmdArgs)
	case "toggle":
		runToggle(cmdArgs)
	case "backup":
		runBackup()
	case "restore":
		runRestore(cmdArgs)
	case "replace":
		runReplace(cmdArgs)
	default:
		fmt.Printf("[✖] error: unknown command %s\n", cmd)
		os.Exit(1)
	}
}

func printHelp() {
	fmt.Println(`
hostctl is a CLI tool to manage your hosts file with ease.
You can have multiple profiles, enable/disable exactly what
you need each time with a simple interface.

Usage:
  hostctl [command]

Available Commands:
  add         Add content to a profile in your hosts file.
  backup      Creates a backup copy of your hosts file
  disable     Disable a profile from your hosts file.
  enable      Enable a profile on your hosts file.
  help        Help about any command
  list        Shows a detailed list of profiles on your hosts file.
  remove      Remove a profile from your hosts file.
  replace     Replace content to a profile in your hosts file.
  restore     Restore hosts file content from a backup file.
  status      Shows a list of profile names and statuses on your hosts file.
  sync        Sync some system IPs with a profile.
  toggle      Change status of a profile on your hosts file.

Flags:
  -c, --column strings     Column names to show on lists. comma separated
  -h, --help               help for hostctl
      --host-file string   Hosts file path (default "/etc/hosts")
      --no-color           force colorless output
  -o, --out string         Output type (table|raw|markdown|json) (default "table")
  -q, --quiet              Run command without output
      --raw                Output without borders (same as -o raw)
  -v, --version            version for hostctl`)
}

func parseHostsFile(path string) (*HostFile, error) {
	file, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return &HostFile{Path: path}, nil
		}
		return nil, err
	}
	defer file.Close()

	hf := &HostFile{Path: path}
	scanner := bufio.NewScanner(file)
	inManaged := false
	var currentProfile *Profile
	headerLines := 0
	var otherLines []string

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		if !inManaged {
			if trimmed == HeaderStart {
				headerLines = 1
				otherLines = append(otherLines, line)
				continue
			}
			if headerLines == 1 && strings.Contains(line, HeaderMiddle) {
				headerLines = 2
				otherLines = append(otherLines, line)
				continue
			}
			if headerLines == 2 && trimmed == HeaderEnd {
				inManaged = true
				otherLines = append(otherLines, line)
				hf.PreHeader = make([]string, len(otherLines)-3)
				copy(hf.PreHeader, otherLines[:len(otherLines)-3])
				continue
			}
			headerLines = 0
			otherLines = append(otherLines, line)
		} else {
			if strings.HasPrefix(trimmed, "# profile.on") {
				name := strings.TrimSpace(strings.TrimPrefix(trimmed, "# profile.on"))
				hf.Profiles = append(hf.Profiles, Profile{Name: name, On: true})
				currentProfile = &hf.Profiles[len(hf.Profiles)-1]
			} else if strings.HasPrefix(trimmed, "# profile.off") {
				name := strings.TrimSpace(strings.TrimPrefix(trimmed, "# profile.off"))
				hf.Profiles = append(hf.Profiles, Profile{Name: name, On: false})
				currentProfile = &hf.Profiles[len(hf.Profiles)-1]
			} else if trimmed == "# end" {
				currentProfile = nil
			} else if currentProfile != nil {
				l := line
				if !currentProfile.On && strings.HasPrefix(trimmed, "#") {
					l = strings.TrimPrefix(trimmed, "#")
				}
				ip, domains, ok := parseLine(l)
				if ok {
					currentProfile.Entries = append(currentProfile.Entries, HostEntry{IP: ip, Domains: domains})
				}
			} else {
				if trimmed != "" {
					hf.PreHeader = append(hf.PreHeader, line)
				}
			}
		}
	}
	if !inManaged {
		hf.PreHeader = otherLines
	}
	return hf, nil
}

func parseLine(line string) (string, []string, bool) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || strings.HasPrefix(trimmed, "#") {
		return "", nil, false
	}
	parts := strings.Fields(trimmed)
	if len(parts) < 2 {
		return "", nil, false
	}
	return parts[0], parts[1:], true
}

func (hf *HostFile) Save() error {
	file, err := os.Create(hf.Path)
	if err != nil {
		return err
	}
	defer file.Close()
	w := bufio.NewWriter(file)
	for _, line := range hf.PreHeader {
		fmt.Fprintln(w, line)
	}
	fmt.Fprintln(w, HeaderStart)
	fmt.Fprintln(w, HeaderMiddle)
	fmt.Fprintln(w, HeaderEnd)
	for _, p := range hf.Profiles {
		fmt.Fprintln(w)
		status := "off"
		if p.On { status = "on" }
		fmt.Fprintf(w, "# profile.%s %s\n", status, p.Name)
		for _, e := range p.Entries {
			line := fmt.Sprintf("%s %s", e.IP, strings.Join(e.Domains, " "))
			if !p.On {
				fmt.Fprintf(w, "# %s\n", line)
			} else {
				fmt.Fprintln(w, line)
			}
		}
		fmt.Fprintln(w, "# end")
	}
	return w.Flush()
}

func runList() {
	if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath) }
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
	var rows []row
	for _, line := range hf.PreHeader {
		ip, domains, ok := parseLine(line)
		if ok {
			for _, d := range domains {
				rows = append(rows, row{"default", "on", ip, d})
			}
		}
	}
	for _, p := range hf.Profiles {
		status := "off"
		if p.On { status = "on" }
		for _, e := range p.Entries {
			for _, d := range e.Domains {
				rows = append(rows, row{p.Name, status, e.IP, d})
			}
		}
	}
	displayRows(rows)
}

func displayRows(rows []row) {
    if outFormat == "json" {
        type jr struct {
            Profile string `json:"Profile"`
            Status  string `json:"Status"`
            IP      string `json:"IP"`
            Host    string `json:"Host"`
        }
        var jrows []jr
        for _, r := range rows {
            jrows = append(jrows, jr{r.profile, r.status, r.ip, r.domain})
        }
        data, _ := json.Marshal(jrows)
        fmt.Println(string(data))
        return
    }
    if outFormat == "raw" {
        for i, col := range columns {
            fmt.Print(col)
            if i < len(columns)-1 { fmt.Print("\t") }
        }
        fmt.Println()
        for _, r := range rows {
            for i, col := range columns {
                switch col {
                case "PROFILE": fmt.Print(r.profile)
                case "STATUS": fmt.Print(r.status)
                case "IP": fmt.Print(r.ip)
                case "DOMAIN": fmt.Print(r.domain)
                }
                if i < len(columns)-1 { fmt.Print("\t") }
            }
            fmt.Println()
        }
        return
    }
    maxWidths := make(map[string]int)
    for _, col := range columns { maxWidths[col] = len(col) }
    for _, r := range rows {
        if len(r.profile) > maxWidths["PROFILE"] { maxWidths["PROFILE"] = len(r.profile) }
        if len(r.status) > maxWidths["STATUS"] { maxWidths["STATUS"] = len(r.status) }
        if len(r.ip) > maxWidths["IP"] { maxWidths["IP"] = len(r.ip) }
        if len(r.domain) > maxWidths["DOMAIN"] { maxWidths["DOMAIN"] = len(r.domain) }
    }
    printSeparator := func() {
        if outFormat == "markdown" {
            fmt.Print("|")
            for _, col := range columns { fmt.Print(strings.Repeat("-", maxWidths[col]+2) + "|") }
            fmt.Println()
            return
        }
        fmt.Print("+")
        for _, col := range columns { fmt.Print(strings.Repeat("-", maxWidths[col]+2) + "+") }
        fmt.Println()
    }
    printRow := func(vals []string) {
        fmt.Print("|")
        for i, v := range vals { fmt.Printf(" %-*s |", maxWidths[columns[i]], v) }
        fmt.Println()
    }
    if outFormat == "table" { printSeparator() }
    printRow(columns)
    printSeparator()
    lastProfile := ""
    for _, r := range rows {
        if outFormat == "table" && lastProfile != "" && lastProfile != r.profile { printSeparator() }
        vals := []string{}
        for _, col := range columns {
            switch col {
            case "PROFILE": vals = append(vals, r.profile)
            case "STATUS": vals = append(vals, r.status)
            case "IP": vals = append(vals, r.ip)
            case "DOMAIN": vals = append(vals, r.domain)
            }
        }
        printRow(vals)
        lastProfile = r.profile
    }
    if outFormat == "table" { printSeparator() }
}

func runStatus() {
	if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath) }
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
