func displayRows(rows []row) {
    if outFormat == "json" {
        type jr struct {
            Profile string `json:"Profile"`
            Status  string `json:"Status"`
            IP      string `json:"IP"`
            Host    string `json:"Host"`
        }
        var jrows []jr
        for _, r := range rows {
            jrows = append(jrows, jr{r.profile, r.status, r.ip, r.domain})
        }
        data, _ := json.Marshal(jrows)
        fmt.Println(string(data))
        return
    }
    if outFormat == "raw" {
        for i, col := range columns {
            fmt.Print(col)
            if i < len(columns)-1 { fmt.Print("\t") }
        }
        fmt.Println()
        for _, r := range rows {
            for i, col := range columns {
                switch col {
                case "PROFILE": fmt.Print(r.profile)
                case "STATUS": fmt.Print(r.status)
                case "IP": fmt.Print(r.ip)
                case "DOMAIN": fmt.Print(r.domain)
                }
                if i < len(columns)-1 { fmt.Print("\t") }
            }
            fmt.Println()
        }
        return
    }
    maxWidths := make(map[string]int)
    for _, col := range columns { maxWidths[col] = len(col) }
    for _, r := range rows {
        if len(r.profile) > maxWidths["PROFILE"] { maxWidths["PROFILE"] = len(r.profile) }
        if len(r.status) > maxWidths["STATUS"] { maxWidths["STATUS"] = len(r.status) }
        if len(r.ip) > maxWidths["IP"] { maxWidths["IP"] = len(r.ip) }
        if len(r.domain) > maxWidths["DOMAIN"] { maxWidths["DOMAIN"] = len(r.domain) }
    }
    printSeparator := func() {
        if outFormat == "markdown" {
            fmt.Print("|")
            for _, col := range columns { fmt.Print(strings.Repeat("-", maxWidths[col]+2) + "|") }
            fmt.Println()
            return
        }
        fmt.Print("+")
        for _, col := range columns { fmt.Print(strings.Repeat("-", maxWidths[col]+2) + "+") }
        fmt.Println()
    }
    printRow := func(vals []string) {
        fmt.Print("|")
        for i, v := range vals { fmt.Printf(" %-*s |", maxWidths[columns[i]], v) }
        fmt.Println()
    }
    if outFormat == "table" { printSeparator() }
    printRow(columns)
    printSeparator()
    lastProfile := ""
    for _, r := range rows {
        if outFormat == "table" && lastProfile != "" && lastProfile != r.profile { printSeparator() }
        vals := []string{}
        for _, col := range columns {
            switch col {
            case "PROFILE": vals = append(vals, r.profile)
            case "STATUS": vals = append(vals, r.status)
            case "IP": vals = append(vals, r.ip)
            case "DOMAIN": vals = append(vals, r.domain)
            }
        }
        printRow(vals)
        lastProfile = r.profile
    }
    if outFormat == "table" { printSeparator() }
}

func runStatus() {
	if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath) }
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    var rows []row
    for _, p := range hf.Profiles {
        status := "off"
        if p.On { status = "on" }
        rows = append(rows, row{profile: p.Name, status: status})
    }
    oldCols := columns
    columns = []string{"PROFILE", "STATUS"}
    displayRows(rows)
    columns = oldCols
}

func runAdd(args []string) {
	if len(args) == 0 { return }
	if args[0] == "domains" || args[0] == "domain" {
		runAddDomains(args[1:])
		return
	}
	profileName := args[0]
	var fromFile string
	for i, arg := range args {
		if (arg == "-f" || arg == "--from") && i+1 < len(args) { fromFile = args[i+1]; break }
	}
	if fromFile == "" {
		fmt.Println("[✖] error: missing profile name or --from file")
		return
	}
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
	entries, err := readEntriesFromFile(fromFile)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
	addEntriesToProfile(hf, profileName, entries)
	err = hf.Save()
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        fmt.Printf("[✔] Profile '%s' added.\n", profileName)
        runList()
    }
}

func runAddDomains(args []string) {
	if len(args) < 2 { return }
	profileName := args[0]
	domains := []string{}
	ip := "127.0.0.1"
	for i := 1; i < len(args); i++ {
		if args[i] == "--ip" && i+1 < len(args) { ip = args[i+1]; i++
		} else { domains = append(domains, args[i]) }
	}
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
	entries := []HostEntry{{IP: ip, Domains: domains}}
	addEntriesToProfile(hf, profileName, entries)
	err = hf.Save()
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        fmt.Printf("[✔] Domains '%s' added.\n\n", strings.Join(domains, ", "))
        runList()
    }
}

func addEntriesToProfile(hf *HostFile, name string, entries []HostEntry) {
	for i, p := range hf.Profiles {
		if p.Name == name { hf.Profiles[i].Entries = append(hf.Profiles[i].Entries, entries...); return }
	}
	hf.Profiles = append(hf.Profiles, Profile{Name: name, On: true, Entries: entries})
}

func readEntriesFromFile(path string) ([]HostEntry, error) {
	file, err := os.Open(path)
	if err != nil { return nil, err }
	defer file.Close()
	var entries []HostEntry
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		ip, domains, ok := parseLine(scanner.Text())
		if ok { entries = append(entries, HostEntry{IP: ip, Domains: domains}) }
	}
	return entries, scanner.Err()
}

func runRemove(args []string) {
    if len(args) == 0 { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    removed := []string{}
    for _, name := range args {
        newProfiles := []Profile{}
        found := false
        for _, p := range hf.Profiles {
            if p.Name == name { found = true; continue }
            newProfiles = append(newProfiles, p)
        }
        if found { hf.Profiles = newProfiles; removed = append(removed, name) }
    }
    err = hf.Save()
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        fmt.Printf("[✔] Profile(s) '%s' removed.\n", strings.Join(removed, ", "))
    }
}

func runEnable(args []string) { runSetStatus(args, true) }
func runDisable(args []string) { runSetStatus(args, false) }
func runSetStatus(args []string, on bool) {
    if len(args) == 0 { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    for _, name := range args {
        found := false
        for i, p := range hf.Profiles {
            if p.Name == name { hf.Profiles[i].On = on; found = true }
        }
        if !found { fmt.Printf("[✖] error: unknown profile %s\n", name) }
    }
    err = hf.Save()
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        runList()
    }
}

func runToggle(args []string) {
    if len(args) == 0 { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    for _, name := range args {
        for i, p := range hf.Profiles {
            if p.Name == name { hf.Profiles[i].On = !hf.Profiles[i].On }
        }
    }
    err = hf.Save()
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        runList()
    }
}

func runBackup() {
    if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath) }
    timestamp := time.Now().Format("20060102")
    backupPath := hostFilePath + "." + timestamp
    input, err := os.ReadFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    err = os.WriteFile(backupPath, input, 0644)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[✔] Backup '%s' created.\n\n", backupPath)
        runList()
    }
}

func runRestore(args []string) {
    var fromFile string
    for i, arg := range args {
        if arg == "--from" && i+1 < len(args) { fromFile = args[i+1]; break }
    }
    if fromFile == "" { return }
    input, err := os.ReadFile(fromFile)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    err = os.WriteFile(hostFilePath, input, 0644)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        fmt.Printf("[✔] File '%s' restored.\n\n", fromFile)
        runList()
    }
}

func runReplace(args []string) {
    if len(args) == 0 { return }
    profileName := args[0]
    var fromFile string
    for i, arg := range args {
        if (arg == "-f" || arg == "--from") && i+1 < len(args) { fromFile = args[i+1]; break }
    }
    if fromFile == "" { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    entries, err := readEntriesFromFile(fromFile)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    found := false
    for i, p := range hf.Profiles {
        if p.Name == profileName { hf.Profiles[i].Entries = entries; found = true; break }
    }
    if !found { hf.Profiles = append(hf.Profiles, Profile{Name: profileName, On: true, Entries: entries}) }
    err = hf.Save()
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        runList()
    }
}
