		} else if arg == "-v" || arg == "--version" { fmt.Println("hostctl version dev"); return
		} else if arg == "-h" || arg == "--help" { printHelp(); return
		} else { newArgs = append(newArgs, arg) }
	}
	if len(newArgs) == 0 { printHelp(); return }
	cmd := newArgs[0]
	cmdArgs := newArgs[1:]
	switch cmd {
	case "list": runList()
	case "status": runStatus()
	case "add": runAdd(cmdArgs)
	case "remove": runRemove(cmdArgs)
	case "enable": runEnable(cmdArgs)
	case "disable": runDisable(cmdArgs)
	case "toggle": runToggle(cmdArgs)
	case "backup": runBackup()
	case "restore": runRestore(cmdArgs)
	case "replace": runReplace(cmdArgs)
	default: fmt.Printf("[✖] error: unknown command %s\n", cmd); os.Exit(1)
	}
}

func printHelp() {
	fmt.Println(`Usage: hostctl [command] [flags] ...`)
}

func parseHostsFile(path string) (*HostFile, error) {
	file, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) { return &HostFile{Path: path}, nil }
		return nil, err
	}
	defer file.Close()
	hf := &HostFile{Path: path}
	scanner := bufio.NewScanner(file)
	var allLines []string
	for scanner.Scan() { allLines = append(allLines, scanner.Text()) }

	headerIdx := -1
	for i := 0; i <= len(allLines)-3; i++ {
		if strings.TrimSpace(allLines[i]) == HeaderStart &&
			strings.Contains(allLines[i+1], HeaderMiddle) &&
			strings.TrimSpace(allLines[i+2]) == HeaderEnd {
			headerIdx = i
			break
		}
	}

	if headerIdx == -1 {
		hf.PreHeader = allLines
		return hf, nil
	}

	hf.PreHeader = allLines[:headerIdx]
	managedLines := allLines[headerIdx+3:]

	var currentProfile *Profile
	for _, line := range managedLines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "# profile.on") {
			name := strings.TrimSpace(strings.TrimPrefix(trimmed, "# profile.on"))
			hf.Profiles = append(hf.Profiles, Profile{Name: name, On: true})
			currentProfile = &hf.Profiles[len(hf.Profiles)-1]
		} else if strings.HasPrefix(trimmed, "# profile.off") {
			name := strings.TrimSpace(strings.TrimPrefix(trimmed, "# profile.off"))
			hf.Profiles = append(hf.Profiles, Profile{Name: name, On: false})
			currentProfile = &hf.Profiles[len(hf.Profiles)-1]
		} else if trimmed == "# end" {
			currentProfile = nil
		} else if currentProfile != nil {
			l := line
			if !currentProfile.On && strings.HasPrefix(trimmed, "#") {
				l = strings.TrimPrefix(trimmed, "#")
			}
			ip, domains, ok := parseLine(l)
			if ok { currentProfile.Entries = append(currentProfile.Entries, HostEntry{IP: ip, Domains: domains}) }
		} else {
            if trimmed != "" {
                hf.PreHeader = append(hf.PreHeader, line)
            }
        }
	}
	return hf, nil
}

func parseLine(line string) (string, []string, bool) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || strings.HasPrefix(trimmed, "#") { return "", nil, false }
	parts := strings.Fields(trimmed)
	if len(parts) < 2 { return "", nil, false }
	return parts[0], parts[1:], true
}

func (hf *HostFile) Save() error {
	file, err := os.Create(hf.Path)
	if err != nil { return err }
	defer file.Close()
	w := bufio.NewWriter(file)
	for _, line := range hf.PreHeader { fmt.Fprintln(w, line) }
	fmt.Fprintln(w, HeaderStart)
	fmt.Fprintln(w, HeaderMiddle)
	fmt.Fprintln(w, HeaderEnd)
	for _, p := range hf.Profiles {
		fmt.Fprintln(w)
		status := "off"
		if p.On { status = "on" }
		fmt.Fprintf(w, "# profile.%s %s\n", status, p.Name)
		for _, e := range p.Entries {
			line := fmt.Sprintf("%s %s", e.IP, strings.Join(e.Domains, " "))
			if !p.On { fmt.Fprintf(w, "# %s\n", line) } else { fmt.Fprintln(w, line) }
		}
		fmt.Fprintln(w, "# end")
	}
	return w.Flush()
}

func runList() {
	if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath) }
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
	var rows []row
	for _, line := range hf.PreHeader {
		ip, domains, ok := parseLine(line)
		if ok { for _, d := range domains { rows = append(rows, row{"default", "on", ip, d}) } }
	}
	for _, p := range hf.Profiles {
		status := "off"
		if p.On { status = "on" }
		for _, e := range p.Entries { for _, d := range e.Domains { rows = append(rows, row{p.Name, status, e.IP, d}) } }
	}
	displayRows(rows)
}

func displayRows(rows []row) {
    if outFormat == "json" {
        type jr struct { Profile string `json:"Profile"`; Status string `json:"Status"`; IP string `json:"IP"`; Host string `json:"Host"` }
        var jrows []jr
        for _, r := range rows { jrows = append(jrows, jr{r.profile, r.status, r.ip, r.domain}) }
        data, _ := json.Marshal(jrows)
        fmt.Println(string(data))
        return
    }
    if outFormat == "raw" {
        for i, col := range columns { fmt.Print(col); if i < len(columns)-1 { fmt.Print("\t") } }; fmt.Println()
        for _, r := range rows {
            for i, col := range columns {
                switch col { case "PROFILE": fmt.Print(r.profile); case "STATUS": fmt.Print(r.status); case "IP": fmt.Print(r.ip); case "DOMAIN": fmt.Print(r.domain) }
                if i < len(columns)-1 { fmt.Print("\t") }
            }
            fmt.Println()
        }
        return
    }
    maxWidths := make(map[string]int)
    for _, col := range columns { maxWidths[col] = len(col) }
    for _, r := range rows {
        if len(r.profile) > maxWidths["PROFILE"] { maxWidths["PROFILE"] = len(r.profile) }
        if len(r.status) > maxWidths["STATUS"] { maxWidths["STATUS"] = len(r.status) }
        if len(r.ip) > maxWidths["IP"] { maxWidths["IP"] = len(r.ip) }
        if len(r.domain) > maxWidths["DOMAIN"] { maxWidths["DOMAIN"] = len(r.domain) }
    }
    printSeparator := func() {
        if outFormat == "markdown" {
            fmt.Print("|")
            for _, col := range columns { fmt.Print(strings.Repeat("-", maxWidths[col]+2) + "|") }
            fmt.Println()
            return
        }
        fmt.Print("+")
        for _, col := range columns { fmt.Print(strings.Repeat("-", maxWidths[col]+2) + "+") }
        fmt.Println()
    }
    printRow := func(vals []string) {
        fmt.Print("|")
        for i, v := range vals { fmt.Printf(" %-*s |", maxWidths[columns[i]], v) }
        fmt.Println()
    }
    if outFormat == "table" { printSeparator() }
    printRow(columns)
    printSeparator()
    lastProfile := ""
    for _, r := range rows {
        if outFormat == "table" && lastProfile != "" && lastProfile != r.profile { printSeparator() }
        vals := []string{}
        for _, col := range columns {
            switch col { case "PROFILE": vals = append(vals, r.profile); case "STATUS": vals = append(vals, r.status); case "IP": vals = append(vals, r.ip); case "DOMAIN": vals = append(vals, r.domain) }
        }
        printRow(vals)
        lastProfile = r.profile
    }
    if outFormat == "table" { printSeparator() }
}

func runStatus() {
	if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath) }
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    var rows []row
    for _, p := range hf.Profiles {
        status := "off"; if p.On { status = "on" }
        rows = append(rows, row{profile: p.Name, status: status})
    }
    oldCols := columns; columns = []string{"PROFILE", "STATUS"}
    displayRows(rows)
    columns = oldCols
}

func runAdd(args []string) {
	if len(args) == 0 { return }
	if args[0] == "domains" || args[0] == "domain" { runAddDomains(args[1:]); return }
	profileName := args[0]
	var fromFile string
	for i, arg := range args { if (arg == "-f" || arg == "--from") && i+1 < len(args) { fromFile = args[i+1]; break } }
	if fromFile == "" { fmt.Println("[✖] error: missing profile name or --from file"); return }
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
	entries, err := readEntriesFromFile(fromFile)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
	addEntriesToProfile(hf, profileName, entries)
	err = hf.Save()
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        fmt.Printf("[✔] Profile '%s' added.\n", profileName)
        runList()
    }
}

func runAddDomains(args []string) {
	if len(args) < 2 { return }
	profileName := args[0]
	domains := []string{}; ip := "127.0.0.1"
	for i := 1; i < len(args); i++ {
		if args[i] == "--ip" && i+1 < len(args) { ip = args[i+1]; i++ } else { domains = append(domains, args[i]) }
	}
	hf, err := parseHostsFile(hostFilePath)
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
	entries := []HostEntry{{IP: ip, Domains: domains}}
	addEntriesToProfile(hf, profileName, entries)
	err = hf.Save()
	if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet {
        fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath)
        fmt.Printf("[✔] Domains '%s' added.\n\n", strings.Join(domains, ", "))
        runList()
    }
}

func addEntriesToProfile(hf *HostFile, name string, entries []HostEntry) {
	for i, p := range hf.Profiles { if p.Name == name { hf.Profiles[i].Entries = append(hf.Profiles[i].Entries, entries...); return } }
	hf.Profiles = append(hf.Profiles, Profile{Name: name, On: true, Entries: entries})
}

func readEntriesFromFile(path string) ([]HostEntry, error) {
	file, err := os.Open(path)
	if err != nil { return nil, err }
	defer file.Close()
	var entries []HostEntry
	scanner := bufio.NewScanner(file)
	for scanner.Scan() { ip, domains, ok := parseLine(scanner.Text()); if ok { entries = append(entries, HostEntry{IP: ip, Domains: domains}) } }
	return entries, scanner.Err()
}

func runRemove(args []string) {
    if len(args) == 0 { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    removed := []string{}
    for _, name := range args {
        newProfiles := []Profile{}; found := false
        for _, p := range hf.Profiles { if p.Name == name { found = true; continue }; newProfiles = append(newProfiles, p) }
        if found { hf.Profiles = newProfiles; removed = append(removed, name) }
    }
    err = hf.Save(); if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath); fmt.Printf("[✔] Profile(s) '%s' removed.\n", strings.Join(removed, ", ")) }
}

func runEnable(args []string) { runSetStatus(args, true) }
func runDisable(args []string) { runSetStatus(args, false) }
func runSetStatus(args []string, on bool) {
    if len(args) == 0 { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    for _, name := range args {
        found := false
        for i, p := range hf.Profiles { if p.Name == name { hf.Profiles[i].On = on; found = true } }
        if !found { fmt.Printf("[✖] error: unknown profile %s\n", name) }
    }
    err = hf.Save(); if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath); runList() }
}

func runToggle(args []string) {
    if len(args) == 0 { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    for _, name := range args {
        for i, p := range hf.Profiles { if p.Name == name { hf.Profiles[i].On = !hf.Profiles[i].On } }
    }
    err = hf.Save(); if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath); runList() }
}

func runBackup() {
    if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath) }
    timestamp := time.Now().Format("20060102")
    backupPath := hostFilePath + "." + timestamp
    input, err := os.ReadFile(hostFilePath); if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    err = os.WriteFile(backupPath, input, 0644); if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet { fmt.Printf("[✔] Backup '%s' created.\n\n", backupPath); runList() }
}

func runRestore(args []string) {
    var fromFile string
    for i, arg := range args { if arg == "--from" && i+1 < len(args) { fromFile = args[i+1]; break } }
    if fromFile == "" { return }
    input, err := os.ReadFile(fromFile); if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    err = os.WriteFile(hostFilePath, input, 0644); if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath); fmt.Printf("[✔] File '%s' restored.\n\n", fromFile); runList() }
}

func runReplace(args []string) {
    if len(args) == 0 { return }
    profileName := args[0]
    var fromFile string
    for i, arg := range args { if (arg == "-f" || arg == "--from") && i+1 < len(args) { fromFile = args[i+1]; break } }
    if fromFile == "" { return }
    hf, err := parseHostsFile(hostFilePath)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    entries, err := readEntriesFromFile(fromFile)
    if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    found := false
    for i, p := range hf.Profiles { if p.Name == profileName { hf.Profiles[i].Entries = entries; found = true; break } }
    if !found { hf.Profiles = append(hf.Profiles, Profile{Name: profileName, On: true, Entries: entries}) }
    err = hf.Save(); if err != nil { fmt.Printf("[✖] error: %v\n", err); return }
    if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFilePath); runList() }
}
