}

func parseLine(line string) (string, []string, bool) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || strings.HasPrefix(trimmed, "#") { return "", nil, false }
	parts := strings.Fields(trimmed)
	if len(parts) < 2 { return "", nil, false }
	return parts[0], parts[1:], true
}

func (hf *HostFile) Save() error {
	file, err := os.Create(hf.Path)
	if err != nil { return err }
	defer file.Close()
	w := bufio.NewWriter(file)
	for _, line := range hf.PreHeader { fmt.Fprintln(w, line) }
	fmt.Fprintln(w, HeaderStart)
	fmt.Fprintln(w, HeaderMiddle)
	fmt.Fprintln(w, HeaderEnd)
	for _, p := range hf.Profiles {
		fmt.Fprintln(w)
		status := "off"; if p.On { status = "on" }
		fmt.Fprintf(w, "# profile.%s %s\n", status, p.Name)
		for _, e := range p.Entries {
			line := fmt.Sprintf("%s %s", e.IP, strings.Join(e.Domains, " "))
			if !p.On { fmt.Fprintf(w, "# %s\n", line) } else { fmt.Fprintln(w, line) }
		}
		fmt.Fprintln(w, "# end")
	}
	return w.Flush()
}

func runList() {
